-- M7: audit log (F30). Generated by a script; triggers record every insert, update and delete
-- on the main tables, whatever code path made it. Updates that only touch timestamps or (for
-- photos) sort order are not recorded. The app adds sign-in events itself.
CREATE TABLE audit_log (
  id INTEGER PRIMARY KEY,
  at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f', 'now')),
  entity TEXT NOT NULL,
  entity_id INTEGER,
  action TEXT NOT NULL,                      -- create | update | delete, or an auth event
  old_row TEXT,                              -- JSON
  new_row TEXT                               -- JSON
);
CREATE INDEX audit_log_entity ON audit_log (entity, entity_id);

CREATE TRIGGER audit_items_insert AFTER INSERT ON items BEGIN
  INSERT INTO audit_log (entity, entity_id, action, new_row) VALUES ('items', NEW.id, 'create', json_object('number', NEW.number, 'name', NEW.name, 'description', NEW.description, 'category_id', NEW.category_id, 'tags', NEW.tags, 'cost_cents', NEW.cost_cents, 'price_cents', NEW.price_cents, 'status', NEW.status, 'notes', NEW.notes, 'archived_at', NEW.archived_at));
END;
CREATE TRIGGER audit_items_update AFTER UPDATE ON items WHEN OLD.number IS NOT NEW.number OR OLD.name IS NOT NEW.name OR OLD.description IS NOT NEW.description OR OLD.category_id IS NOT NEW.category_id OR OLD.tags IS NOT NEW.tags OR OLD.cost_cents IS NOT NEW.cost_cents OR OLD.price_cents IS NOT NEW.price_cents OR OLD.status IS NOT NEW.status OR OLD.notes IS NOT NEW.notes OR OLD.archived_at IS NOT NEW.archived_at BEGIN
  INSERT INTO audit_log (entity, entity_id, action, old_row, new_row)
  VALUES ('items', NEW.id, 'update', json_object('number', OLD.number, 'name', OLD.name, 'description', OLD.description, 'category_id', OLD.category_id, 'tags', OLD.tags, 'cost_cents', OLD.cost_cents, 'price_cents', OLD.price_cents, 'status', OLD.status, 'notes', OLD.notes, 'archived_at', OLD.archived_at), json_object('number', NEW.number, 'name', NEW.name, 'description', NEW.description, 'category_id', NEW.category_id, 'tags', NEW.tags, 'cost_cents', NEW.cost_cents, 'price_cents', NEW.price_cents, 'status', NEW.status, 'notes', NEW.notes, 'archived_at', NEW.archived_at));
END;
CREATE TRIGGER audit_items_delete AFTER DELETE ON items BEGIN
  INSERT INTO audit_log (entity, entity_id, action, old_row) VALUES ('items', OLD.id, 'delete', json_object('number', OLD.number, 'name', OLD.name, 'description', OLD.description, 'category_id', OLD.category_id, 'tags', OLD.tags, 'cost_cents', OLD.cost_cents, 'price_cents', OLD.price_cents, 'status', OLD.status, 'notes', OLD.notes, 'archived_at', OLD.archived_at));
END;

CREATE TRIGGER audit_categories_insert AFTER INSERT ON categories BEGIN
  INSERT INTO audit_log (entity, entity_id, action, new_row) VALUES ('categories', NEW.id, 'create', json_object('name', NEW.name));
END;
CREATE TRIGGER audit_categories_update AFTER UPDATE ON categories WHEN OLD.name IS NOT NEW.name BEGIN
  INSERT INTO audit_log (entity, entity_id, action, old_row, new_row)
  VALUES ('categories', NEW.id, 'update', json_object('name', OLD.name), json_object('name', NEW.name));
END;
CREATE TRIGGER audit_categories_delete AFTER DELETE ON categories BEGIN
  INSERT INTO audit_log (entity, entity_id, action, old_row) VALUES ('categories', OLD.id, 'delete', json_object('name', OLD.name));
END;

