CREATE TRIGGER audit_settings_delete AFTER DELETE ON settings BEGIN
  INSERT INTO audit_log (entity, entity_id, action, old_row) VALUES ('settings', NULL, 'delete', json_object('key', OLD.key, 'value', OLD.value));
END;

